#include <iostream>
#include <memory>
#include <vector>
#include <utility>
#include <string>

struct Box { std::unique_ptr<int> p; explicit Box(int x): p(std::make_unique<int>(x)) {} Box(const Box&) = delete; Box& operator=(const Box& x) { auto next = std::make_unique<int>(*x.p); p = std::move(next); return *this; } };
int solve(int a, int b) { Box x{a}, y{b}; x = y; Box& alias = x; x = alias; *y.p = a; return *x.p + *y.p; }
